def norm(shape):
    mr=min(r for r,c in shape); mc=min(c for r,c in shape)
    return frozenset((r-mr,c-mc) for r,c in shape)
def dihedral(shape):
    arr=set()
    for refl in [1,-1]:
      for k in range(4):
        pts=[]
        for r,c in shape:
          c*=refl
          for _ in range(k): r,c=c,-r
          pts.append((r,c))
        arr.add(norm(pts))
    return arr
def occurrences(grid, shape, val=0):
    H=len(grid);W=len(grid[0]); found=[]
    for sh in dihedral(shape):
      h=max(r for r,c in sh)+1; w=max(c for r,c in sh)+1
      for r in range(H-h+1):
       for c in range(W-w+1):
        if all(grid[r+dr][c+dc]==val for dr,dc in sh):
         found.extend((r+dr,c+dc) for dr,dc in sh)
    return set(found)
